CREATE TABLE public.marketing_automations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,category text not null check(category in('funnel','automation')),trigger_type text not null,conditions jsonb not null default '{}'::jsonb,actions jsonb not null default '[]'::jsonb,status text not null default 'draft' check(status in('draft','active','paused','archived')),approval_required boolean not null default true,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE public.marketing_automation_runs (id uuid primary key default gen_random_uuid(),automation_id uuid not null references public.marketing_automations(id) on delete cascade,organization_id uuid not null references public.organizations(id),dedupe_key text not null,status text not null default 'queued' check(status in('queued','running','completed','failed','cancelled')),scheduled_for timestamptz not null default now(),started_at timestamptz,finished_at timestamptz,error_detail text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(automation_id,dedupe_key));
ALTER TABLE public.marketing_automations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.marketing_automation_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY marketing_automations_org ON public.marketing_automations FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_automations.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager'))) WITH CHECK(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_automations.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager')));
CREATE POLICY marketing_automation_runs_org ON public.marketing_automation_runs FOR SELECT TO authenticated USING(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_automation_runs.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager')));
CREATE OR REPLACE FUNCTION public.set_marketing_automation_status(p_id uuid,p_status text) RETURNS public.marketing_automations LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ declare v public.marketing_automations; begin select * into v from public.marketing_automations where id=p_id for update; if not found or auth.uid() is null or not(public.is_admin(auth.uid()) or exists(select 1 from public.organization_members m where m.organization_id=v.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager'))) or p_status not in('active','paused','archived') then raise exception 'Automação inválida ou sem permissão'; end if; update public.marketing_automations set status=p_status,updated_at=now() where id=v.id returning * into v; if p_status='paused' then update public.marketing_automation_runs set status='cancelled',finished_at=now() where automation_id=v.id and status in('queued','running'); end if; return v; end $$;
REVOKE ALL ON FUNCTION public.set_marketing_automation_status(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_marketing_automation_status(uuid,text) TO authenticated;

